    let mut sign = 1_i32;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    if index >= bytes.len() || !bytes[index].is_ascii_digit() {
        return None;
    }

    let mut magnitude: i64 = 0;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        magnitude = magnitude.saturating_mul(10);
        magnitude = magnitude.saturating_add((bytes[index] - b'0') as i64);
        if magnitude > i32::MAX as i64 {
            return None;
        }
        index += 1;
    }

    let value = (sign as i64) * magnitude;
    if !(0..=65535).contains(&value) {
        return None;
    }

    Some(value as i32)
}

